import{_ as t,o,c as a,ae as r}from"./chunks/framework.CSxHcPWC.js";const p=JSON.parse('{"title":"Where Sentinel applies","description":"","frontmatter":{},"headers":[],"relativePath":"enforcement.md","filePath":"enforcement.md"}'),d={name:"enforcement.md"};function n(s,e,c,i,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="where-sentinel-applies" tabindex="-1">Where Sentinel applies <a class="header-anchor" href="#where-sentinel-applies" aria-label="Permalink to &quot;Where Sentinel applies&quot;">​</a></h1><p>Sentinel returns a verdict. It does not sit in front of a website by itself. Your app, edge worker, or game server enforces that verdict. A URL that never calls Sentinel is unchanged.</p><p>Put the check on the routes that matter — signup, login, checkout, or every HTTP request — and leave the rest of the site alone.</p><hr><h2 id="precheck-and-evaluate" tabindex="-1">Precheck and evaluate <a class="header-anchor" href="#precheck-and-evaluate" aria-label="Permalink to &quot;Precheck and evaluate&quot;">​</a></h2><p>These are different calls. Use one for a hint, the other for the decision you enforce.</p><table tabindex="0"><thead><tr><th></th><th><code>GET /v1/precheck</code></th><th><code>POST /v2/evaluate</code></th></tr></thead><tbody><tr><td>Caller</td><td>Browser or edge. No API key.</td><td>Your server, with the billing key. Each call counts against quota.</td></tr><tr><td>Engine</td><td>V1. It may wait on a live IP lookup.</td><td>V2. Memory and cache, then the saved policy.</td></tr><tr><td>Mode, VPN, datacenter, Force BWT</td><td>Not used.</td><td>Used.</td></tr><tr><td>Trust token</td><td>Ignored.</td><td><code>x-sentinel-trust</code> is checked. A valid token passes Force BWT.</td></tr><tr><td>Answer</td><td><code>TRUSTED</code>, <code>UNSTABLE</code>, or <code>UNTRUSTED</code>, plus <code>required</code>.</td><td><code>ALLOW</code>, <code>CHALLENGE</code>, or <code>BLOCK</code>.</td></tr><tr><td>What you do</td><td><code>required: false</code> — continue. <code>required: true</code> — show the widget.</td><td><code>ALLOW</code> forwards the request. <code>CHALLENGE</code> shows the widget, then retry with the token. <code>BLOCK</code> rejects it.</td></tr></tbody></table><p>A site key will not authenticate <code>/v2/evaluate</code>. Keep the billing key on the server. The widget in the browser uses the site key only for <code>/v1/challenge/issue</code> and <code>/v1/challenge/verify</code>.</p><hr><h2 id="the-saved-mode-after-a-challenge" tabindex="-1">The saved mode after a challenge <a class="header-anchor" href="#the-saved-mode-after-a-challenge" aria-label="Permalink to &quot;The saved mode after a challenge&quot;">​</a></h2><p>The widget does not choose a mode. <code>/v2/evaluate</code> loads the Global Master Policy for that API key on every call.</p><p>Force BWT is on by default. The first evaluate, with no <code>x-sentinel-trust</code> header, returns <code>CHALLENGE</code> before Passive, Balanced, Strict, Draconian, or Humans only is consulted. That is true for a clean residential IP.</p><p>The visitor then uses the hold widget or the click widget. Either one solves the same proof and returns a trust token. The widget does not send the mode.</p><p>Your server retries <code>/v2/evaluate</code> with <code>x-sentinel-trust</code>. Force BWT steps aside, and the saved mode runs.</p><p>After a valid token, Passive, Balanced, Strict, and Draconian return <code>ALLOW</code>. Humans only still requires a residential IP together with the token, and it still blocks a scanner signature or a velocity spike.</p><p>With Force BWT off, the saved mode decides the first call. A clean IP on Balanced can be <code>ALLOW</code> with no widget. Show the widget only when that mode returns <code>CHALLENGE</code>.</p><hr><h2 id="a-datacenter-block-and-the-rest-of-the-site" tabindex="-1">A datacenter block and the rest of the site <a class="header-anchor" href="#a-datacenter-block-and-the-rest-of-the-site" aria-label="Permalink to &quot;A datacenter block and the rest of the site&quot;">​</a></h2><p><code>datacenter_action: block</code> applies only to requests that call <code>/v2/evaluate</code> with that policy. A blog, a marketing page, or any other URL that does not call Sentinel is not filtered. Crawlers can still fetch those pages.</p><p>On the protected route, two details matter.</p><p><strong>Known crawlers.</strong> Googlebot, Bingbot, and the other listed crawlers are <code>VERIFIED_BOT</code> when their User-Agent is the one Sentinel sees. A verified bot skips the datacenter hard block and Force BWT. The mode still runs. This works only if the evaluate call forwards the crawler&#39;s User-Agent. If your server calls Sentinel with its own User-Agent, a Google datacenter IP is treated like any other datacenter and a hard block rejects it on that route.</p><p><strong>Edge broadcast.</strong> A <code>BLOCK</code> can be written to Cloudflare KV as <code>sentinel:verdict:&lt;ip&gt;</code> for about one hour, and only when <code>CLOUDFLARE_API_KEY</code>, the account id, and the KV namespace are set. That write does nothing to the rest of the site unless an edge worker on the zone reads the same key and blocks the IP. With no such worker, other pages stay unaffected.</p><hr><h2 id="same-engine-different-gate" tabindex="-1">Same engine, different gate <a class="header-anchor" href="#same-engine-different-gate" aria-label="Permalink to &quot;Same engine, different gate&quot;">​</a></h2><p>The decision engine is one. The gate is wherever you enforce the verdict.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Placement</th><th>What it covers</th></tr></thead><tbody><tr><td>Route shield</td><td>Your API calls <code>/v2/evaluate</code> on signup, login, or checkout.</td><td>Those routes only.</td></tr><tr><td>Site gate</td><td>A Cloudflare Worker or reverse proxy calls evaluate for every HTTP request and drops <code>BLOCK</code> before the origin.</td><td>HTTP through that worker. Not packets, SSH, or UDP.</td></tr><tr><td>Game or other server</td><td>The server calls evaluate and closes the session on <code>BLOCK</code>.</td><td>The calls that server chooses to check.</td></tr></tbody></table><p>A site gate is an application check on HTTP. It is not a network firewall.</p>',27)])])}const f=t(d,[["render",n]]);export{p as __pageData,f as default};
